-- Courriels des préréglages d'automatisation — normes du 2026-09-29.
--
-- Généré (script de session, entrées : fonctions de prod, anciens et nouveaux
-- server/lib/automationPresets.data.ts / automationPack.data.ts, backfill
-- 20260909180000). Quatre volets :
--
-- A. seed_automation_presets : chaque courriel est posé en FR (subject/body)
--    + EN (subject_en/body_en). Le seed écrivait l'ANGLAIS dans subject/body :
--    une entreprise francophone envoyait « We missed you! », « How was your
--    experience? », « Thank you! », « Payment Received » à ses clients.
-- B. apply_automation_presets_fr : mêmes textes FR (objets sans « [company_name] — »).
-- C. Règles existantes : un courriel n'est remplacé que si CHACUN de ses textes
--    est un texte connu d'une version livrée par Lume (seed, traduction FR,
--    fichier de données, backfill) — un texte personnalisé laisse l'action
--    intacte. Répare aussi les champs EN croisés par le backfill du 2026-09-09
--    (copié par POSITION : le texto avait reçu le HTML du courriel).
-- D. Parcours du pack de base : remplacés seulement s'ils sont identiques à la
--    version livrée.
--
-- Idempotent : relancée, elle réécrit les mêmes textes.

-- ═══ A ═══
CREATE OR REPLACE FUNCTION public.seed_automation_presets(p_org_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
BEGIN

  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  --  QUOTE FOLLOW-UPS (5)
  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 1 Day', 'Friendly follow-up 1 day after quote sent', 'quote.sent', '{}'::jsonb, 86400,
    '[{"type":"send_sms","config":{"body":"Hi [client_first_name], just following up on the quote we sent yesterday. Have you had a chance to review it? Let us know if you have any questions! — [company_name]"}},{"type":"send_email","config":{"subject":"Avez-vous bien reçu votre soumission?","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>On vous a envoyé une soumission hier et on voulait s''assurer que vous l''avez bien reçue.</p><p>Des questions? Répondez à ce courriel, ça nous fera plaisir d''y répondre.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Did you receive your quote?","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We sent you a quote yesterday and wanted to make sure it reached you.</p><p>Any questions? Just reply to this email — we''d be happy to answer them.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_1d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 3 Days', 'Gentle reminder 3 days after quote sent', 'quote.sent', '{}'::jsonb, 259200,
    '[{"type":"send_sms","config":{"body":"Hi [client_first_name], we wanted to check in about the quote we sent a few days ago. — [company_name]"}},{"type":"send_email","config":{"subject":"Votre soumission vous attend","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Petit rappel au sujet de la soumission qu''on vous a envoyée.</p><p>Si un détail ne convient pas, on peut l''ajuster — dites-le-nous simplement.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Your quote is waiting for you","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Just a reminder about the quote we sent you.</p><p>If any detail doesn''t work for you, we can adjust it — just let us know.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_3d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 7 Days', 'Follow-up 7 days after quote sent', 'quote.sent', '{}'::jsonb, 604800,
    '[{"type":"send_email","config":{"subject":"Des questions sur votre soumission?","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Avez-vous eu le temps de regarder votre soumission?</p><p>Si vous avez des questions ou souhaitez aller de l''avant, répondez à ce courriel.</p><p>Au plaisir,<br/>[company_name]</p></div>","subject_en":"Any questions about your quote?","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Have you had a chance to look at your quote?</p><p>If you have any questions or would like to move ahead, reply to this email.</p><p>Looking forward,<br/>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_7d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 14 Days', 'Last chance follow-up 14 days after quote sent', 'quote.sent', '{}'::jsonb, 1209600,
    '[{"type":"send_email","config":{"subject":"Dernière relance pour votre soumission","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>On voulait faire un dernier suivi au sujet de votre soumission.</p><p>Si le moment n''est pas bon, aucun souci — répondez-nous et on se reprendra quand ça vous conviendra.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Final follow-up on your quote","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We wanted to do one last follow-up about your quote.</p><p>If now isn''t the right time, no problem — just reply and we''ll reconnect whenever it suits you.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_14d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Estimate Follow-Up (3 days)', 'Follow-up 3 days after estimate sent', 'estimate.sent', '{}'::jsonb, 259200,
    '[{"type":"send_email","config":{"subject":"Suivi de votre devis","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>On vous a envoyé un devis récemment et on voulait faire un suivi.</p><p>Des questions? Répondez à ce courriel, ça nous fera plaisir d''y répondre.</p><p>Cordialement,<br/>[company_name]</p></div>","subject_en":"Following up on your estimate","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We sent you an estimate recently and wanted to follow up.</p><p>Any questions? Just reply to this email — we''d be happy to answer them.</p><p>Best regards,<br/>[company_name]</p></div>"}},{"type":"send_sms","config":{"body":"Hi [client_first_name], just following up on the estimate we sent. Let us know if you have any questions! — [company_name]"}}]'::jsonb,
    true, true, 'estimate_followup')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  --  INVOICE REMINDERS (5)
  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES
    (p_org_id, 'Invoice Reminder — 1 Day', 'Reminder 1 day after invoice sent', 'invoice.sent', '{}'::jsonb, 86400,
     '[{"type":"send_email","config":{"subject":"Rappel : facture [invoice_number]","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Petit rappel amical : la facture <strong>[invoice_number]</strong> de <strong>[invoice_total]</strong> est en attente de paiement.</p><p>Si vous avez déjà payé, ignorez ce message.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Reminder: invoice [invoice_number]","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Just a friendly reminder: invoice <strong>[invoice_number]</strong> for <strong>[invoice_total]</strong> is awaiting payment.</p><p>If you''ve already paid, please disregard this message.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
     true, true, 'invoice_sent_reminder_1d'),
    (p_org_id, 'Invoice Reminder — 3 Days', 'Reminder 3 days after invoice sent', 'invoice.sent', '{}'::jsonb, 259200,
     '[{"type":"send_email","config":{"subject":"Facture [invoice_number] toujours en attente","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>La facture <strong>[invoice_number]</strong> de <strong>[invoice_total]</strong> est toujours en attente de paiement.</p><p>Si vous avez déjà payé, ignorez ce message.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Invoice [invoice_number] still awaiting payment","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Invoice <strong>[invoice_number]</strong> for <strong>[invoice_total]</strong> is still awaiting payment.</p><p>If you''ve already paid, please disregard this message.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
     true, true, 'invoice_sent_reminder_3d'),
    (p_org_id, 'Invoice Reminder — 7 Days', 'Reminder 7 days after invoice sent', 'invoice.sent', '{}'::jsonb, 604800,
     '[{"type":"send_email","config":{"subject":"Facture [invoice_number] en attente depuis 7 jours","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>La facture <strong>[invoice_number]</strong> de <strong>[invoice_total]</strong> est en attente depuis une semaine.</p><p>Merci de la régler dès que possible, ou répondez à ce courriel si quelque chose ne va pas.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Invoice [invoice_number] pending for 7 days","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Invoice <strong>[invoice_number]</strong> for <strong>[invoice_total]</strong> has been pending for a week.</p><p>Please settle it as soon as possible, or reply to this email if something isn''t right.</p><p>Thank you,<br/>[company_name]</p></div>"}}]'::jsonb,
     true, true, 'invoice_sent_reminder_7d'),
    (p_org_id, 'Invoice Reminder — 30 Days', 'Final reminder 30 days after invoice sent', 'invoice.sent', '{}'::jsonb, 2592000,
     '[{"type":"send_email","config":{"subject":"Facture [invoice_number] en souffrance depuis 30 jours","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>La facture <strong>[invoice_number]</strong> de <strong>[invoice_total]</strong> est en souffrance depuis 30 jours.</p><p>Merci de la régler sans tarder, ou contactez-nous pour convenir d''une entente de paiement.</p><p>Merci,<br/>[company_name]</p></div>","subject_en":"Invoice [invoice_number] overdue for 30 days","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Invoice <strong>[invoice_number]</strong> for <strong>[invoice_total]</strong> has been overdue for 30 days.</p><p>Please settle it without further delay, or contact us to arrange a payment plan.</p><p>Thank you,<br/>[company_name]</p></div>"}},{"type":"create_notification","config":{"title":"Invoice [invoice_number] — 30 days overdue","body":"[client_name] has an invoice overdue for 30 days."}},{"type":"create_task","config":{"title":"Follow up: Invoice [invoice_number] — 30 days overdue"}}]'::jsonb,
     true, true, 'invoice_sent_reminder_30d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  --  LEADS (3)
  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Welcome New Lead', 'Send welcome message when a new lead is created', 'lead.created', '{}'::jsonb, 0,
