      {"type":"create_notification","config":{"title":"New lead: [client_name]","body":"A new lead has been created."}}]'::jsonb,
    true, true, 'welcome_new_lead')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

