  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'No-Show Follow-Up', 'Follow up when appointment is cancelled or no-show', 'appointment.cancelled', '{}'::jsonb, 3600,
    '[{"type":"send_email","config":{"subject":"Votre rendez-vous a été annulé","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Votre rendez-vous a été annulé.</p><p>Si vous souhaitez le reprendre, répondez à ce courriel et on vous trouvera un moment qui vous convient.</p><p>Au plaisir,<br/>[company_name]</p></div>","subject_en":"Your appointment was cancelled","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Your appointment was cancelled.</p><p>If you would like to reschedule, reply to this email and we will find a time that works for you.</p><p>Talk soon,<br/>[company_name]</p></div>"}}]'::jsonb,
