END;
$function$;

CREATE OR REPLACE FUNCTION public.seed_agreement_signed_preset(p_org_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.automation_rules
    (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  select
    o.id,
    'Contract Signed',
    'Confirm to the client that their contract is signed',
    'agreement.signed',
    '{}'::jsonb,
    0,
    '[{"type":"send_sms","config":{"body":"Merci [client_first_name]! Votre contrat avec [company_name] est signé. Votre copie : [signed_contract_link]\n[deposit_line]"}},{"type":"send_email","config":{"subject":"Votre contrat est signé","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Merci [client_first_name],</h2><p>Votre contrat avec [company_name] est signé. Vous pouvez le consulter en tout temps ici :</p><p><a href=\"[signed_contract_link]\">Consulter votre contrat signé</a></p><p>[deposit_line]</p><p>À bientôt!<br/>[company_name]</p></div>","subject_en":"Your contract is signed","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Thank you [client_first_name],</h2><p>Your contract with [company_name] is signed. You can view it anytime here:</p><p><a href=\"[signed_contract_link]\">View your signed contract</a></p><p>[deposit_line]</p><p>Talk soon!<br/>[company_name]</p></div>"}}]'::jsonb,
    true,
    true,
    'agreement_signed'
  from public.orgs o
  where p_org_id is null or o.id = p_org_id
  -- L'index unique est PARTIEL (where preset_key is not null) : le ON CONFLICT
  -- doit répéter la même clause, sinon Postgres ne reconnaît pas l'index.
  on conflict (org_id, preset_key) where preset_key is not null do nothing;
end;
$function$;

-- ═══ B ═══
CREATE OR REPLACE FUNCTION public.apply_automation_presets_fr(p_org_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  with fr(preset_key, sms, email_subject, email_body) as (
    values
      ('appointment_confirmation',
       'Bonjour [client_first_name], votre rendez-vous avec [company_name] est confirmé pour le [appointment_date] à [appointment_time]. À bientôt!',
       'Votre rendez-vous est confirmé',
