create function public._courriel_normalise(p_key text, a jsonb) returns jsonb
language plpgsql as $fn$
declare
  c public._courriels_canon%rowtype;
  cfg jsonb := a->'config';
  f text;
  connu boolean := true;
  en text;
begin
  if a->>'type' = 'send_email' then
    select * into c from public._courriels_canon where preset_key = p_key;
    if not found then return a; end if;
    foreach f in array array['subject','body','subject_en','body_en'] loop
      if cfg ? f and coalesce(cfg->>f, '') <> '' then
        connu := connu and exists (
          select 1 from public._courriels_connus k
           where k.preset_key = p_key and k.texte = cfg->>f
             and (k.genre = 'courriel' or f = 'body_en'));
      end if;
    end loop;
    if not connu then return a; end if;
    return jsonb_set(a, '{config}', cfg || jsonb_build_object(
      'subject', c.subject, 'subject_en', c.subject_en, 'body', c.body, 'body_en', c.body_en));
  end if;

  if a->>'type' in ('send_sms', 'create_notification')
     and cfg->>'body_en' like '<%'
     and exists (select 1 from public._courriels_connus k
                  where k.preset_key = p_key and k.genre = 'courriel' and k.texte = cfg->>'body_en') then
    select e.body_en into en from public._courriels_en_autres e
     where e.preset_key = p_key and e.type = a->>'type' limit 1;
    cfg := cfg - 'body_en';
    if en is not null then cfg := cfg || jsonb_build_object('body_en', en); end if;
    if exists (select 1 from public._courriels_connus k
                where k.preset_key = p_key and k.genre = 'courriel' and k.texte = cfg->>'subject_en') then
      cfg := cfg - 'subject_en';
    end if;
    return jsonb_set(a, '{config}', cfg);
  end if;
  return a;
end $fn$;

with normalisees as (
  select r.id,
         (select jsonb_agg(public._courriel_normalise(r.preset_key, t.a) order by t.ord)
            from jsonb_array_elements(r.actions) with ordinality as t(a, ord)) as actions
    from public.automation_rules r
   where r.preset_key is not null and r.deleted_at is null
     and jsonb_typeof(r.actions) = 'array' and jsonb_array_length(r.actions) > 0
)
update public.automation_rules r
   set actions = n.actions, updated_at = now()
  from normalisees n
 where r.id = n.id and n.actions is distinct from r.actions;

drop function public._courriel_normalise(text, jsonb);
drop table public._courriels_en_autres;
drop table public._courriels_connus;
drop table public._courriels_canon;

