update public.automation_rules
   set steps = '[{"id":"e1","type":"action","action":{"type":"send_sms","config":{"body":"Bonjour [client_first_name], merci d''avoir contacté [company_name]! On revient vers vous très vite.","body_en":"Hi [client_first_name], thank you for contacting [company_name]! We''ll get back to you very soon."}},"nom":"Bienvenue","suivant":"e2"},{"id":"e2","type":"action","action":{"type":"send_email","config":{"subject":"Merci de nous avoir contactés","subject_en":"Thanks for reaching out","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2 style=\"color:#1a1a1a;font-size:18px;\">Bonjour [client_first_name],</h2><p style=\"color:#333;line-height:1.6;\">Merci d''avoir communiqué avec nous. Nous avons bien reçu votre demande et nous revenons vers vous très rapidement.</p><p style=\"color:#333;line-height:1.6;\">Si votre demande est urgente, répondez à ce courriel — nous la traiterons en priorité.</p><p style=\"color:#333;line-height:1.6;\">[company_name]</p></div>","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2 style=\"color:#1a1a1a;font-size:18px;\">Hi [client_first_name],</h2><p style=\"color:#333;line-height:1.6;\">Thank you for reaching out to us. We''ve received your request and will get back to you very quickly.</p><p style=\"color:#333;line-height:1.6;\">If your request is urgent, reply to this email — we''ll handle it as a priority.</p><p style=\"color:#333;line-height:1.6;\">[company_name]</p></div>"}},"nom":"Bienvenue","suivant":"e3"},{"id":"e3","type":"action","action":{"type":"create_notification","config":{"body":"[client_name] — [client_phone]","title":"Nouveau prospect"}},"nom":"Bienvenue","suivant":"e4"},{"id":"e4","type":"attendre","delai_secondes":86400,"suivant":"e5"},{"id":"e5","type":"action","action":{"type":"send_sms","config":{"body":"Bonjour [client_first_name], avez-vous toujours besoin de nos services? Répondez à ce message et on s''occupe de vous. — [company_name]","body_en":"Hi [client_first_name], do you still need our services? Reply to this message and we''ll take care of you. — [company_name]"}},"nom":"Relance 1 jour","suivant":"e6"},{"id":"e6","type":"attendre","delai_secondes":172800,"suivant":"e7"},{"id":"e7","type":"action","action":{"type":"send_email","config":{"body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Vous nous avez contactés récemment et on veut s''assurer de ne pas vous laisser sans réponse.</p><p>Répondez à ce courriel et on s''occupe de vous rapidement.</p><p>Merci,<br/>[company_name]</p></div>","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>You reached out to us recently and we want to make sure we don''t leave you without an answer.</p><p>Reply to this email and we''ll take care of you right away.</p><p>Thank you,<br/>[company_name]</p></div>","subject":"Votre demande n''est pas oubliée","subject_en":"We haven''t forgotten your request"}},"nom":"Relance 3 jours","suivant":"e8"},{"id":"e8","type":"attendre","delai_secondes":950400,"suivant":"e9"},{"id":"e9","type":"action","action":{"type":"send_email","config":{"body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Bonjour [client_first_name],</h2><p>Ça fait deux semaines depuis votre demande — êtes-vous toujours à la recherche de nos services?</p><p>Un simple mot et on vous prépare une soumission.</p><p>Au plaisir,<br/>[company_name]</p></div>","body_en":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>It''s been two weeks since your request — are you still looking for our services?</p><p>Just say the word and we''ll put together a quote for you.</p><p>Looking forward,<br/>[company_name]</p></div>","subject":"Votre projet est-il toujours d''actualité?","subject_en":"Is your project still on?"}},"nom":"Relance 14 jours","suivant":"e10"},{"id":"e10","type":"action","action":{"type":"create_task","config":{"title":"Prospect sans réponse — [client_name]","body":"Aucune réponse depuis 14 jours. Faire un dernier appel, ou clore le dossier."}},"nom":"Relance 14 jours","suivant":"e11"},{"id":"e11","type":"action","action":{"type":"create_notification","config":{"body":"[client_name] ne répond plus. Une tâche de suivi a été créée.","title":"Prospect sans réponse — 14 jours"}},"nom":"Relance 14 jours","suivant":null}]'::jsonb,
